import os
import binascii


def import_settings_from_environment_variables(config):
    """Import settings from environment variables into config."""
    settings = {}
    for key, value in os.environ.items():
        if key.startswith('SYNCSERVER_'):
            setting_key = key[len('SYNCSERVER_'):].lower()
            settings[setting_key] = str_to_bool(value) if value.lower() in ('true', 'false') else value
    config.update(settings)
    return config


def str_to_bool(value):
    """Convert string to boolean."""
    return value.lower() in ('true', '1', 'yes')


def generate_random_hex_key(length=32):
    """Generate a random hex key of specified length."""
    return binascii.hexlify(os.urandom(length // 2)).decode('ascii')
